import React, { useMemo, useCallback } from 'react';
import {
    Box,
    Typography,
    TextField,
    Select,
    MenuItem,
    FormControl
} from '@mui/material';
import FontPicker from 'react-fontpicker-ts';
import 'react-fontpicker-ts/dist/index.css';
import type { PlacedElement } from '../types/FrameEngine2_LayoutTypes';
import { useColorPicker } from '../FrameEngine2_ColorPickerContext';
import { PIXEL_FONTS } from '../FrameEngine2_FontLoader';

/**
 * Props for color input component
 */
interface ColorInputProps {
    label: string;
    value: string;
    onChange: (value: string) => void;
    error?: boolean;
    disabled?: boolean;
}

/**
 * Reusable color input with global picker and text field
 */
export const ColorInput: React.FC<ColorInputProps> = React.memo(({
    label,
    value,
    onChange,
    error = false,
    disabled = false
}) => {
    const currentValue = value ?? '#ffffff';
    const colorPicker = useColorPicker();

    // Get display color for the swatch
    const getSwatchColor = () => {
        if (!currentValue || currentValue === 'transparent') {
            return 'transparent';
        }
        return currentValue;
    };

    // Open the global color picker using context (only if not disabled)
    const handleSwatchClick = useCallback(() => {
        if (!disabled) {
            colorPicker.open(currentValue, (newColor: string) => {
                onChange(newColor);
            });
        }
    }, [colorPicker, currentValue, onChange, disabled]);

    return (
        <Box sx={{ mb: 1 }}>
            <Typography variant="caption" color={error ? 'error' : 'text.secondary'} display="block" mb={0.5}>
                {label}{error && ' (Required)'}
            </Typography>
            <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
                {/* Color swatch button */}
                <Box
                    onClick={handleSwatchClick}
                    sx={{
                        width: '48px',
                        height: '40px',
                        border: error ? '2px solid #d32f2f' : '1px solid #ccc',
                        borderRadius: '4px',
                        backgroundColor: getSwatchColor(),
                        backgroundImage: currentValue === 'transparent'
                            ? 'linear-gradient(45deg, #ccc 25%, transparent 25%, transparent 75%, #ccc 75%, #ccc), linear-gradient(45deg, #ccc 25%, transparent 25%, transparent 75%, #ccc 75%, #ccc)'
                            : 'none',
                        backgroundSize: '8px 8px',
                        backgroundPosition: '0 0, 4px 4px',
                        cursor: disabled ? 'not-allowed' : 'pointer',
                        opacity: disabled ? 0.5 : 1,
                        '&:hover': disabled ? {} : {
                            opacity: 0.8
                        }
                    }}
                />

                {/* Text input */}
                <TextField
                    size="small"
                    fullWidth
                    value={currentValue}
                    onChange={(e) => onChange(e.target.value)}
                    error={error}
                    disabled={disabled}
                    sx={{ fontFamily: 'monospace' }}
                />
            </Box>

            {/* Help text */}
            <Typography variant="caption" color="text.disabled" display="block" mt={0.5} fontSize="10px">
                Supports hex, rgb(), rgba(), hsl(), hsla(), or 'transparent'
            </Typography>
        </Box>
    );
});

ColorInput.displayName = 'ColorInput';

/**
 * Props for text/number input component
 */
interface TextInputProps {
    label: string;
    value: string | number;
    onChange: (value: string | number) => void;
    type?: 'text' | 'number';
    error?: boolean;
    helperText?: string;
    placeholder?: string;
    step?: number;
}

/**
 * Reusable text/number input
 */
export const TextInput: React.FC<TextInputProps> = React.memo(({
    label,
    value,
    onChange,
    type = 'text',
    error = false,
    helperText = '',
    placeholder = '',
    step
}) => {
    const handleChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
        if (type === 'number') {
            const val = e.target.value;
            if (val === '') {
                onChange('');
            } else {
                const parsed = parseFloat(val);
                onChange(isNaN(parsed) ? 0 : parsed);
            }
        } else {
            onChange(e.target.value);
        }
    }, [type, onChange]);

    const handleBlur = useCallback((e: React.FocusEvent<HTMLInputElement>) => {
        if (type === 'number' && e.target.value === '') {
            onChange(0);
        }
    }, [type, onChange]);

    return (
        <Box sx={{ mb: 1 }}>
            <TextField
                label={label}
                type={type}
                size="small"
                fullWidth
                value={value ?? ''}
                onChange={handleChange}
                onBlur={handleBlur}
                error={error}
                helperText={helperText || (error ? 'Required field' : '')}
                placeholder={placeholder}
                sx={{ '& input': { fontFamily: 'monospace' } }}
                inputProps={step !== undefined ? { step } : undefined}
            />
        </Box>
    );
});

TextInput.displayName = 'TextInput';

/**
 * Props for font family select component
 */
interface FontFamilySelectProps {
    value: string;
    onChange: (value: string) => void;
}

/**
 * Reusable Google Fonts dropdown with live previews
 * Uses react-fontpicker-ts with autoLoad to handle all font loading
 */
export const FontFamilySelect: React.FC<FontFamilySelectProps> = React.memo(({
    value: currentValue,
    onChange
}) => {
    return (
        <Box sx={{ mb: 1 }}>
            <Typography variant="caption" color="text.secondary" display="block" mb={0.5}>
                Font Family
            </Typography>
            <FontPicker
                defaultValue={currentValue || 'Inter'}
                value={onChange}
                autoLoad={true}
            />
        </Box>
    );
});

FontFamilySelect.displayName = 'FontFamilySelect';

/**
 * Props for font source picker component
 */
interface FontSourcePickerProps {
    value: 'google' | 'pixel';
    onChange: (value: 'google' | 'pixel') => void;
}

/**
 * Font source picker - Choose between Google Fonts and Pixel Fonts
 */
export const FontSourcePicker: React.FC<FontSourcePickerProps> = React.memo(({
    value,
    onChange
}) => {
    return (
        <Box sx={{ mb: 1 }}>
            <Typography variant="caption" color="text.secondary" display="block" mb={0.5}>
                Font Source
            </Typography>
            <FormControl fullWidth size="small">
                <Select
                    value={value}
                    onChange={(e) => onChange(e.target.value as 'google' | 'pixel')}
                    sx={{ fontFamily: 'monospace' }}
                >
                    <MenuItem value="google">Google Fonts</MenuItem>
                    <MenuItem value="pixel">Pixel Fonts</MenuItem>
                </Select>
            </FormControl>
            <Typography variant="caption" color="text.disabled" display="block" mt={0.5} fontSize="10px">
                {value === 'pixel'
                    ? 'Pixel-perfect bitmap fonts for retro aesthetics'
                    : 'Modern scalable fonts from Google Fonts'}
            </Typography>
        </Box>
    );
});

FontSourcePicker.displayName = 'FontSourcePicker';

/**
 * Props for pixel font select component
 */
interface PixelFontSelectProps {
    value: string;
    onChange: (value: string) => void;
}

/**
 * Pixel font picker - Select from available pixel fonts
 */
export const PixelFontSelect: React.FC<PixelFontSelectProps> = React.memo(({
    value,
    onChange
}) => {
    // Ensure value is valid, default to first pixel font if not
    const safeValue = PIXEL_FONTS.includes(value as any) ? value : PIXEL_FONTS[0];

    return (
        <Box sx={{ mb: 1 }}>
            <Typography variant="caption" color="text.secondary" display="block" mb={0.5}>
                Font Family
            </Typography>
            <FormControl fullWidth size="small">
                <Select
                    value={safeValue}
                    onChange={(e) => onChange(e.target.value)}
                    sx={{ fontFamily: 'monospace' }}
                >
                    {PIXEL_FONTS.map((font) => (
                        <MenuItem key={font} value={font} style={{ fontFamily: font }}>
                            {font}
                        </MenuItem>
                    ))}
                </Select>
            </FormControl>
            <Typography variant="caption" color="text.disabled" display="block" mt={0.5} fontSize="10px">
                Pixel fonts render best at specific sizes (8px, 12px, 16px, 24px)
            </Typography>
        </Box>
    );
});

PixelFontSelect.displayName = 'PixelFontSelect';

/**
 * Props for typography controls group
 */
interface TypographyControlsProps {
    fontFamily: string;
    fontSize: number;
    textColor: string;
    backgroundColor: string;
    onChange: (property: string, value: any) => void;
    textColorPropertyName?: string; // Property name to use for text color (default: 'textColor')
    fontType?: 'google' | 'pixel'; // Optional font type - if provided, shows font source picker
    supportsFontType?: boolean; // Whether this element supports font type switching (default: false)
    onFontTypeChange?: (newType: 'google' | 'pixel') => void; // Optional batched update handler for font type changes
}

/**
 * Reusable typography controls group (font family, size, colors)
 * Supports optional font type picker for elements that can use pixel fonts
 */
export const TypographyControls: React.FC<TypographyControlsProps> = React.memo(({
    fontFamily,
    fontSize,
    textColor,
    backgroundColor,
    onChange,
    textColorPropertyName = 'textColor',
    fontType,
    supportsFontType = false,
    onFontTypeChange
}) => {
    // Default handler for font type changes (for Text elements that don't provide custom handler)
    const defaultFontTypeChange = useCallback((newType: 'google' | 'pixel') => {
        onChange('fontType', newType);

        // Set appropriate default font family for the new type
        if (newType === 'pixel') {
            onChange('fontFamily', PIXEL_FONTS[0]); // Default to first pixel font
        } else {
            onChange('fontFamily', 'Inter'); // Default to Inter for Google Fonts
        }
    }, [onChange]);

    // Use provided handler or fall back to default
    // onFontTypeChange allows parent component to batch updates properly (Architecture Guidelines Section 1.1)
    const handleFontTypeChange = onFontTypeChange || defaultFontTypeChange;

    return (
        <>
            {/* Show font source picker if element supports font type */}
            {supportsFontType && (
                <FontSourcePicker
                    value={fontType || 'google'}
                    onChange={handleFontTypeChange}
                />
            )}

            {/* Show appropriate font picker based on font type */}
            {supportsFontType ? (
                fontType === 'pixel' ? (
                    <PixelFontSelect
                        value={fontFamily}
                        onChange={(v) => onChange('fontFamily', v)}
                    />
                ) : (
                    <FontFamilySelect
                        value={fontFamily}
                        onChange={(v) => onChange('fontFamily', v)}
                    />
                )
            ) : (
                <FontFamilySelect
                    value={fontFamily}
                    onChange={(v) => onChange('fontFamily', v)}
                />
            )}

            <TextInput
                label="Font Size"
                type="number"
                value={fontSize}
                onChange={(v) => onChange('fontSize', v)}
            />
            <ColorInput
                label="Text Color"
                value={textColor}
                onChange={(v) => onChange(textColorPropertyName, v)}
            />
            <ColorInput
                label="Background Color"
                value={backgroundColor}
                onChange={(v) => onChange('backgroundColor', v)}
            />
        </>
    );
});

TypographyControls.displayName = 'TypographyControls';

/**
 * Hook to create property update function
 * Handles both top-level (x, y) and nested (properties.text) updates
 * @param value - Property value (legitimately `any` - different properties have different types)
 */
export const usePropertyUpdate = (
    selectedElement: PlacedElement,
    onUpdateElement: (elementId: string, updates: Partial<PlacedElement>) => void
) => {
    return useCallback((propertyPath: string, value: any) => {
        if (propertyPath.includes('.')) {
            // Nested property (e.g., "properties.text")
            const [parent, key] = propertyPath.split('.');
            // All PlacedElement variants have a 'properties' field
            if (parent === 'properties') {
                onUpdateElement(selectedElement.id, {
                    properties: {
                        ...selectedElement.properties,
                        [key]: value
                    }
                } as Partial<PlacedElement>);
            }
        } else {
            // Top-level property (e.g., "x", "y")
            onUpdateElement(selectedElement.id, { [propertyPath]: value });
        }
    }, [selectedElement, onUpdateElement]);
};

/**
 * Hook to get property value with default
 * Supports both top-level and nested properties
 * @param defaultValue - Default value if property doesn't exist (legitimately `any` - properties have varying types)
 */
export const usePropertyValue = (selectedElement: PlacedElement) => {
    return useCallback((propertyPath: string, defaultValue: any = '') => {
        if (propertyPath.includes('.')) {
            // Nested property (e.g., "properties.text")
            const [parent, key] = propertyPath.split('.');
            // All PlacedElement variants have a 'properties' field
            if (parent === 'properties') {
                return (selectedElement.properties as Record<string, any>)?.[key] ?? defaultValue;
            }
            return defaultValue;
        } else {
            // Top-level property (e.g., "x", "y")
            return selectedElement[propertyPath as keyof PlacedElement] ?? defaultValue;
        }
    }, [selectedElement]);
};

/**
 * Common property update function for properties object
 * Shorthand for updating element.properties.* values
 * @param value - Property value (legitimately `any` - different properties have different types)
 */
export const usePropertiesUpdate = (
    selectedElement: PlacedElement,
    onUpdateElement: (elementId: string, updates: Partial<PlacedElement>) => void
) => {
    return useCallback((property: string, value: any) => {
        onUpdateElement(selectedElement.id, {
            properties: {
                ...selectedElement.properties,
                [property]: value
            }
        } as Partial<PlacedElement>);
    }, [selectedElement, onUpdateElement]);
};
