import React, { useState, useCallback, useMemo } from 'react';

/**
 * Props for the PixelDraw element component
 */
interface PixelDrawElementProps {
    /** Element properties */
    properties: {
        pixelSize?: number;
        gridColor?: string;
        showGrid?: boolean;
        backgroundColor?: string;
        pixels?: Record<string, string>;
        [key: string]: any;
    };

    /** Element padding in pixels */
    elementPadding?: number;

    /** Element dimensions */
    width: number;
    height: number;

    /** Callback to update element properties */
    onUpdateProperties?: (updates: any) => void;
}

/**
 * PixelDraw Element - Pixel art drawing canvas
 *
 * STUB IMPLEMENTATION - Full functionality to be added:
 * - Click/drag to draw pixels
 * - Right-click to erase
 * - Color picker integration
 * - Undo/redo support
 * - Export pixel data
 */
const FrameEngine2_Element_PixelDraw: React.FC<PixelDrawElementProps> = ({
    properties,
    elementPadding = 4,
    width,
    height,
    onUpdateProperties
}) => {
    const {
        pixelSize = 8,
        gridColor = '#333333',
        showGrid = true,
        backgroundColor = '#000000',
        pixels = {}
    } = properties;

    const [isDrawing, setIsDrawing] = useState(false);
    const [currentColor] = useState('#FF0000'); // TODO: Integrate with color picker context

    // Calculate grid dimensions
    const gridWidth = Math.floor((width - elementPadding * 2) / pixelSize);
    const gridHeight = Math.floor((height - elementPadding * 2) / pixelSize);

    /**
     * Convert pixel coordinate to grid coordinate
     */
    const getGridCoordinate = useCallback((clientX: number, clientY: number, rect: DOMRect) => {
        const x = Math.floor((clientX - rect.left - elementPadding) / pixelSize);
        const y = Math.floor((clientY - rect.top - elementPadding) / pixelSize);

        if (x >= 0 && x < gridWidth && y >= 0 && y < gridHeight) {
            return { x, y };
        }
        return null;
    }, [pixelSize, gridWidth, gridHeight, elementPadding]);

    /**
     * Handle mouse down - start drawing
     */
    const handleMouseDown = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
        const rect = e.currentTarget.getBoundingClientRect();
        if (!rect) return;

        const coord = getGridCoordinate(e.clientX, e.clientY, rect);
        if (coord) {
            setIsDrawing(true);
            const key = `${coord.x},${coord.y}`;

            // Update pixels
            const newPixels = { ...pixels };
            if (e.button === 2) {
                // Right click - erase
                delete newPixels[key];
            } else {
                // Left click - draw
                newPixels[key] = currentColor;
            }

            onUpdateProperties?.({ pixels: newPixels });
        }
    }, [pixels, currentColor, getGridCoordinate, onUpdateProperties]);

    /**
     * Render the pixel grid
     */
    const gridStyle = useMemo(() => ({
        width: width - elementPadding * 2,
        height: height - elementPadding * 2,
        backgroundColor,
        border: showGrid ? `1px solid ${gridColor}` : 'none',
        position: 'relative' as const,
        cursor: 'crosshair',
        imageRendering: 'pixelated' as const,
        display: 'grid',
        gridTemplateColumns: `repeat(${gridWidth}, ${pixelSize}px)`,
        gridTemplateRows: `repeat(${gridHeight}, ${pixelSize}px)`,
        gap: showGrid ? '1px' : '0',
        padding: 0,
        margin: elementPadding
    }), [width, height, elementPadding, backgroundColor, showGrid, gridColor, gridWidth, gridHeight, pixelSize]);

    return (
        <div
            style={{
                width: '100%',
                height: '100%',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                backgroundColor: 'transparent'
            }}
        >
            <div style={gridStyle} onContextMenu={(e) => e.preventDefault()}>
                {/* Render pixels */}
                {Array.from({ length: gridHeight }, (_, y) =>
                    Array.from({ length: gridWidth }, (_, x) => {
                        const key = `${x},${y}`;
                        const pixelColor = pixels[key];
                        return (
                            <div
                                key={key}
                                style={{
                                    width: pixelSize,
                                    height: pixelSize,
                                    backgroundColor: pixelColor || 'transparent',
                                    border: showGrid ? `1px solid ${gridColor}` : 'none',
                                    boxSizing: 'border-box'
                                }}
                                onMouseDown={handleMouseDown}
                                onMouseEnter={(e) => {
                                    if (isDrawing) {
                                        // Continue drawing while dragging
                                        const rect = (e.target as HTMLElement).getBoundingClientRect();
                                        const coord = getGridCoordinate(e.clientX, e.clientY, rect);
                                        if (coord) {
                                            const newPixels = { ...pixels };
                                            newPixels[`${coord.x},${coord.y}`] = currentColor;
                                            onUpdateProperties?.({ pixels: newPixels });
                                        }
                                    }
                                }}
                            />
                        );
                    })
                )}
            </div>

            {/* Stub message - Remove when fully implemented */}
            <div
                style={{
                    position: 'absolute',
                    bottom: elementPadding,
                    right: elementPadding,
                    background: 'rgba(0,0,0,0.7)',
                    color: 'white',
                    padding: '2px 6px',
                    fontSize: '10px',
                    borderRadius: '2px',
                    pointerEvents: 'none'
                }}
            >
                PixelDraw (Stub)
            </div>
        </div>
    );
};

export default React.memo(FrameEngine2_Element_PixelDraw);