/* eslint-disable react/jsx-pascal-case */
// Note: Component names use underscore naming convention for namespace organization (FrameEngine2_*)
// This is a deliberate architectural choice and does not violate PascalCase - the components ARE PascalCase

import React, { useState, useRef, useMemo, useCallback, lazy, Suspense } from 'react';
import type { PlacedElement, GridSettings } from './types/FrameEngine2_LayoutTypes';
import type {
    DiscoveredRiveStateMachine,
    DiscoveredRiveDataBinding
} from './types/FrameEngine2_ElementTypes';
import { hasSensorTag, getSensorTag } from './types/FrameEngine2_TypeGuards';
import { deepEqual } from '../../utils/deepEqual';
import FrameEngine2_Element_Sensor from './elements/FrameEngine2_Element_Sensor';
import FrameEngine2_Element_Text from './elements/FrameEngine2_Element_Text';
import FrameEngine2_Element_TimeDate from './elements/FrameEngine2_Element_TimeDate';
import FrameEngine2_Element_MediaImage from './elements/FrameEngine2_Element_MediaImage';
import FrameEngine2_Element_MediaVideo from './elements/FrameEngine2_Element_MediaVideo';
import FrameEngine2_Element_PixelDraw from './elements/FrameEngine2_Element_PixelDraw';

// Lazy load heavy components to reduce initial bundle size
const FrameEngine2_Element_Gauge = lazy(() => import('./elements/FrameEngine2_Element_Gauge')); // Uses Recharts (~100KB)
const FrameEngine2_Element_MediaRive = lazy(() => import('./elements/FrameEngine2_Element_MediaRive')); // Uses Rive library (~150KB)
const FrameEngine2_Element_ECG = lazy(() => import('./elements/FrameEngine2_Element_ECG')); // Heavy waveform rendering
const FrameEngine2_Element_Tunnel = lazy(() => import('./elements/FrameEngine2_Element_Tunnel')); // Canvas-based animation
const FrameEngine2_Element_Weather = lazy(() => import('./elements/FrameEngine2_Element_Weather')); // Three.js 3D scene

interface FrameEngine2_Renderer_ElementsProps {
    /** Element to render */
    element: PlacedElement;

    /** Whether this element is currently selected */
    isSelected?: boolean;

    /** Callback when element is clicked */
    onClick?: (elementId: string) => void;

    /** Callback when element is updated (e.g., dragged) */
    onUpdateElement?: (elementId: string, updates: Partial<PlacedElement>) => void;

    /** Resolved sensor values (Live > Test hierarchy already applied) */
    resolvedValues: Record<string, any>;

    /** Whether to show placeholders when no data */
    showPlaceholders?: boolean;

    /** Element padding in pixels */
    elementPadding?: number;

    /** Grid settings for snapping */
    grid?: GridSettings;

    /** Layout mode for determining snapping behavior ('composite' or 'pixel') */
    layoutMode?: 'composite' | 'pixel';

    /** Preview mode - disables selection and editing */
    previewMode?: boolean;

    /** Callback for Rive discovery (MediaRive elements only) */
    onRiveDiscovery?: (elementId: string, machines: DiscoveredRiveStateMachine[], bindings: DiscoveredRiveDataBinding[]) => void;
}

/**
 * Element Renderer - Dispatches to the correct element component
 * and handles positioning, selection, resize, and rotation
 */
const FrameEngine2_Renderer_Elements: React.FC<FrameEngine2_Renderer_ElementsProps> = ({
    element,
    isSelected = false,
    onClick,
    onUpdateElement,
    resolvedValues,
    showPlaceholders = true,
    elementPadding = 4,
    grid,
    layoutMode = 'composite',
    previewMode = false,
    onRiveDiscovery
}) => {
    // Hover state for border highlighting
    const [isHovered, setIsHovered] = useState(false);

    // Ref for Moveable target element
    const targetRef = useRef<HTMLDivElement>(null);

    /**
     * Extract element-specific resolved values to prevent unnecessary re-renders
     * OPTIMIZATION: Only extract the sensor data this element actually needs,
     * so the element doesn't re-render when unrelated sensors change
     */
    const elementSpecificResolvedValues = useMemo(() => {
        // Sensor, gauge, and ECG elements only need their specific sensor tag
        if (hasSensorTag(element)) {
            const sensorTag = getSensorTag(element);
            if (sensorTag) {
                const sensorValue = resolvedValues[sensorTag];
                // Return object with only this sensor to maintain component interface
                return sensorValue !== undefined ? { [sensorTag]: sensorValue } : {};
            }
        }

        // Media elements don't use resolvedValues
        if (element.type.startsWith('media-')) {
            return {};
        }

        // Time/date and text elements don't use resolvedValues
        if (element.type === 'timedate' || element.type === 'text') {
            return {};
        }

        // Fallback: return full resolvedValues for other element types
        return resolvedValues;
    }, [element.type, element.properties, resolvedValues]);

    /**
     * Stable reference for element properties
     * OPTIMIZATION: Only changes when properties actually change (deep comparison)
     * Uses deepEqual instead of JSON.stringify for better performance
     */
    const propertiesRef = useRef(element.properties);
    const stableProperties = useMemo(() => {
        if (!deepEqual(propertiesRef.current, element.properties)) {
            propertiesRef.current = element.properties;
        }
        return propertiesRef.current;
    }, [element.properties]);

    /**
     * Render the appropriate element component based on type
     * Memoized to prevent expensive element recreation (especially for Gauge)
     */
    const renderedElement = useMemo(() => {
        // Capture type for use in default case (discriminated union narrows to never)
        const elementType = element.type;

        // console.log(`[Renderer] Element ${element.id} (${elementType}) receiving values:`, resolvedValues);
        
        switch (elementType) {
            case 'sensor':
                return (
                    <FrameEngine2_Element_Sensor
                        properties={element.properties}
                        resolvedValues={elementSpecificResolvedValues}
                        showPlaceholders={showPlaceholders}
                        elementPadding={elementPadding}
                        width={element.width}
                        height={element.height}
                    />
                );

            case 'text':
                return (
                    <FrameEngine2_Element_Text
                        properties={element.properties}
                        elementPadding={elementPadding}
                        width={element.width}
                        height={element.height}
                    />
                );

            case 'gauge':
                return (
                    <Suspense fallback={<div style={{ width: '100%', height: '100%', background: '#f5f5f5' }} />}>
                        <FrameEngine2_Element_Gauge
                            properties={element.properties}
                            resolvedValues={elementSpecificResolvedValues}
                            showPlaceholders={showPlaceholders}
                            elementPadding={elementPadding}
                            width={element.width}
                            height={element.height}
                        />
                    </Suspense>
                );

            case 'timedate':
                return (
                    <FrameEngine2_Element_TimeDate
                        properties={element.properties}
                        elementPadding={elementPadding}
                        width={element.width}
                        height={element.height}
                    />
                );

            case 'media-image':
                return (
                    <FrameEngine2_Element_MediaImage
                        properties={element.properties}
                        width={element.width}
                        height={element.height}
                    />
                );

            case 'media-video':
                return (
                    <FrameEngine2_Element_MediaVideo
                        properties={element.properties}
                        width={element.width}
                        height={element.height}
                    />
                );

            case 'media-rive':
                return (
                    <Suspense fallback={<div style={{ width: '100%', height: '100%', background: '#f5f5f5' }} />}>
                        <FrameEngine2_Element_MediaRive
                            elementId={element.id}
                            properties={element.properties}
                            width={element.width}
                            height={element.height}
                            onRiveDiscovery={onRiveDiscovery}
                        />
                    </Suspense>
                );

            case 'ecg':
                return (
                    <Suspense fallback={<div style={{ width: '100%', height: '100%', background: '#f5f5f5' }} />}>
                        <FrameEngine2_Element_ECG
                            properties={element.properties}
                            resolvedValues={elementSpecificResolvedValues}
                            showPlaceholders={showPlaceholders}
                            elementPadding={elementPadding}
                            width={element.width}
                            height={element.height}
                        />
                    </Suspense>
                );

            case 'tunnel':
                return (
                    <Suspense fallback={<div style={{ width: '100%', height: '100%', background: '#f5f5f5' }} />}>
                        <FrameEngine2_Element_Tunnel
                            properties={element.properties}
                            width={element.width}
                            height={element.height}
                        />
                    </Suspense>
                );

            case 'weather':
                return (
                    <Suspense fallback={<div style={{ width: '100%', height: '100%', background: '#f5f5f5' }} />}>
                        <FrameEngine2_Element_Weather
                            properties={element.properties}
                            width={element.width}
                            height={element.height}
                            previewMode={previewMode}
                        />
                    </Suspense>
                );

            case 'pixel-draw':
                return (
                    <FrameEngine2_Element_PixelDraw
                        properties={element.properties}
                        width={element.width}
                        height={element.height}
                        onUpdateProperties={(updates) => {
                            // TODO: Connect to onUpdateElement when available
                            console.log('[PixelDraw] Property updates:', updates);
                        }}
                    />
                );

            default:
                // TypeScript knows this is unreachable for valid types
                // but we keep it for runtime safety
                return (
                    <div
                        style={{
                            width: '100%',
                            height: '100%',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            fontSize: '12px',
                            color: '#999'
                        }}
                    >
                        Unknown: {elementType}
                    </div>
                );
        }
    // OPTIMIZED: Use stableProperties for stable reference and elementSpecificResolvedValues to prevent re-renders on unrelated sensor changes
    // stableProperties only changes when properties content actually changes (deep equality check with deepEqual)
    // previewMode included to enable Weather element's preserveDrawingBuffer for GIF capture
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [element.type, stableProperties, element.width, element.height, element.id, elementSpecificResolvedValues, showPlaceholders, elementPadding, previewMode, onRiveDiscovery]);

    /**
     * Handle click - select element
     * OPTIMIZATION: Wrapped in useCallback
     */
    const handleClick = useCallback((e: React.MouseEvent) => {
        e.stopPropagation();
        onClick?.(element.id);
    }, [onClick, element.id]);

    /**
     * Handle mouse enter for hover state
     * OPTIMIZATION: State-based styling instead of direct DOM manipulation
     */
    const handleMouseEnter = useCallback(() => {
        if (!isSelected) {
            setIsHovered(true);
        }
    }, [isSelected]);

    /**
     * Handle mouse leave for hover state
     * OPTIMIZATION: State-based styling instead of direct DOM manipulation
     */
    const handleMouseLeave = useCallback(() => {
        setIsHovered(false);
    }, []);

    /**
     * Memoized element wrapper style
     * OPTIMIZATION: Prevents object recreation on every render
     */
    const elementWrapperStyle = useMemo(() => {
        // Determine border based on state
        // Use 1px border in pixel mode, 2px in composite mode
        const borderWidth = layoutMode === 'pixel' ? '1px' : '2px';
        let border;
        if (isSelected) {
            border = `${borderWidth} solid #2196f3`;
        } else if (isHovered) {
            border = `${borderWidth} solid rgba(33, 150, 243, 0.5)`;
        } else if (grid?.showOutlines) {
            // Show outlines for all elements when showOutlines is enabled
            border = `${borderWidth} solid rgba(128, 128, 128, 0.3)`;
        } else {
            border = `${borderWidth} solid transparent`;
        }

        return {
            position: 'absolute' as const,
            transform: `translate(${element.x}px, ${element.y}px) rotate(${element.rotation}deg)`,
            width: `${element.width}px`,
            height: `${element.height}px`,
            cursor: previewMode ? 'default' : 'pointer',
            border,
            boxSizing: 'border-box' as const,
            transition: 'border-color 0.15s ease',
            pointerEvents: (element.locked || previewMode ? 'none' : 'auto') as 'none' | 'auto',
            zIndex: element.zIndex,
            userSelect: 'none' as const
        };
    }, [element.x, element.y, element.width, element.height, element.rotation, element.zIndex, element.locked, isSelected, isHovered, grid?.showOutlines, previewMode, layoutMode]);

    return (
        <>
            <div
                ref={targetRef}
                data-element-id={element.id}
                onClick={!isSelected ? handleClick : undefined}
                onMouseEnter={handleMouseEnter}
                onMouseLeave={handleMouseLeave}
                style={elementWrapperStyle}
            >
                {renderedElement}
            </div>
        </>
    );
};

export default React.memo(FrameEngine2_Renderer_Elements);

