import { useState, useEffect, useMemo } from 'react';
import type { PlacedElement } from '../types/FrameEngine2_LayoutTypes';

/**
 * Test Data Generator Hook
 *
 * Generates mock sensor values for preview mode when no live data is available.
 * Supports different data types and animation patterns.
 */

interface TestDataConfig {
    /** Elements to extract sensor tags from */
    elements: PlacedElement[];
    /** Whether to animate values (cycling/changing) */
    animate?: boolean;
    /** Animation interval in ms */
    animationInterval?: number;
}

interface SensorDataType {
    type: 'number' | 'string' | 'waveform';
    min?: number;
    max?: number;
    pattern?: 'random' | 'sine' | 'linear';
}

/**
 * Extract all sensor tags from elements
 */
function extractSensorTags(elements: PlacedElement[]): string[] {
    const tags = new Set<string>();

    elements.forEach(element => {
        // Sensor elements
        if (element.type === 'sensor' && element.properties.sensorTag) {
            tags.add(element.properties.sensorTag);
        }
        // Gauge elements
        if (element.type === 'gauge' && element.properties.sensorTag) {
            tags.add(element.properties.sensorTag);
        }
        // ECG elements
        if (element.type === 'ecg' && element.properties.sensorTag) {
            tags.add(element.properties.sensorTag);
        }
    });

    return Array.from(tags);
}

/**
 * Determine data type and range for a sensor tag
 */
function getSensorDataType(sensorTag: string): SensorDataType {
    const tag = sensorTag.toLowerCase();

    // ECG/waveform patterns
    if (tag.includes('ecg') || tag.includes('waveform') || tag.includes('wave')) {
        return { type: 'waveform', min: -1, max: 1, pattern: 'sine' };
    }

    // Temperature sensors
    if (tag.includes('temp') || tag.includes('temperature')) {
        return { type: 'number', min: 60, max: 100, pattern: 'sine' };
    }

    // Pressure sensors
    if (tag.includes('pressure') || tag.includes('psi')) {
        return { type: 'number', min: 0, max: 150, pattern: 'sine' };
    }

    // Speed/RPM sensors
    if (tag.includes('speed') || tag.includes('rpm') || tag.includes('velocity')) {
        return { type: 'number', min: 0, max: 8000, pattern: 'sine' };
    }

    // Percentage/battery
    if (tag.includes('percent') || tag.includes('battery') || tag.includes('charge')) {
        return { type: 'number', min: 0, max: 100, pattern: 'sine' };
    }

    // Voltage
    if (tag.includes('volt') || tag.includes('voltage')) {
        return { type: 'number', min: 0, max: 24, pattern: 'sine' };
    }

    // Status/text values
    if (tag.includes('status') || tag.includes('state') || tag.includes('mode')) {
        return { type: 'string' };
    }

    // Default: numeric with reasonable range
    return { type: 'number', min: 0, max: 100, pattern: 'sine' };
}

/**
 * Generate a value based on data type and animation phase
 */
function generateValue(dataType: SensorDataType, phase: number): any {
    if (dataType.type === 'string') {
        const states = ['Active', 'Ready', 'Idle', 'Running'];
        return states[Math.floor(phase * states.length) % states.length];
    }

    if (dataType.type === 'number' || dataType.type === 'waveform') {
        const { min = 0, max = 100, pattern = 'sine' } = dataType;
        const range = max - min;

        if (pattern === 'sine') {
            // Sine wave oscillation
            return min + (Math.sin(phase * Math.PI * 2) * 0.5 + 0.5) * range;
        } else if (pattern === 'linear') {
            // Linear cycling
            return min + (phase % 1) * range;
        } else {
            // Random with smooth transitions
            const baseValue = min + (Math.sin(phase * Math.PI * 2) * 0.5 + 0.5) * range;
            const randomOffset = (Math.random() - 0.5) * range * 0.1;
            return Math.max(min, Math.min(max, baseValue + randomOffset));
        }
    }

    return 0;
}

/**
 * Hook to generate and manage test sensor data
 */
export function useTestDataGenerator({ elements, animate = true, animationInterval = 100 }: TestDataConfig) {
    const [phase, setPhase] = useState(0);

    // Extract sensor tags from elements
    const sensorTags = useMemo(() => extractSensorTags(elements), [elements]);

    // Map sensor tags to data types
    const sensorDataTypes = useMemo(() => {
        const types: Record<string, SensorDataType> = {};
        sensorTags.forEach(tag => {
            types[tag] = getSensorDataType(tag);
        });
        return types;
    }, [sensorTags]);

    // Animate phase if enabled
    useEffect(() => {
        if (!animate) return;

        const interval = setInterval(() => {
            setPhase(p => (p + 0.01) % 1);
        }, animationInterval);

        return () => clearInterval(interval);
    }, [animate, animationInterval]);

    // Generate current sensor values based on phase
    const testValues = useMemo(() => {
        const values: Record<string, any> = {};

        sensorTags.forEach(tag => {
            const dataType = sensorDataTypes[tag];
            values[tag] = generateValue(dataType, phase);
        });

        return values;
    }, [sensorTags, sensorDataTypes, phase]);

    return {
        testValues,
        sensorTags,
        phase
    };
}

/**
 * Generate static test data manifest for export
 */
export function generateTestDataManifest(elements: PlacedElement[]): Record<string, any> {
    const sensorTags = extractSensorTags(elements);
    const testData: Record<string, any> = {};

    sensorTags.forEach(tag => {
        const dataType = getSensorDataType(tag);
        // Generate mid-range values for static export
        testData[tag] = generateValue(dataType, 0.5);
    });

    return testData;
}
