import React from 'react';
import {
    Box,
    Typography,
    FormControlLabel,
    Checkbox,
    Select,
    MenuItem,
    FormControl,
    InputLabel
} from '@mui/material';
import type { ElementPropertyPanelProps } from './FrameEngine2_ElementProperties_Types';
import {
    TextInput,
    ColorInput,
    usePropertiesUpdate
} from './FrameEngine2_ElementProperties_Shared';

/**
 * Properties panel for 3D Weather elements
 */
export const WeatherProperties: React.FC<ElementPropertyPanelProps> = ({
    selectedElement,
    onUpdateElement
}) => {
    // Hook must be called before any conditional returns
    const updateProperty = usePropertiesUpdate(selectedElement, onUpdateElement);

    // Type guard: This component is only rendered for weather elements
    if (selectedElement.type !== 'weather') {
        return null;
    }

    return (
        <Box>
            <Typography variant="subtitle2" fontWeight="bold" mb={1}>
                3D Weather Effect Properties
            </Typography>

            {/* Scene Settings */}
            <Typography variant="caption" color="text.secondary" display="block" mb={0.5} mt={1}>
                SCENE
            </Typography>

            <FormControl fullWidth size="small" sx={{ mb: 1 }}>
                <InputLabel>Weather Type</InputLabel>
                <Select
                    value={selectedElement.properties.weatherType || 'clear'}
                    label="Weather Type"
                    onChange={(e) => updateProperty('weatherType', e.target.value)}
                >
                    <MenuItem value="clear">Clear</MenuItem>
                    <MenuItem value="cloudy">Cloudy</MenuItem>
                    <MenuItem value="rainy">Rainy</MenuItem>
                    <MenuItem value="snowy">Snowy</MenuItem>
                    <MenuItem value="stormy">Stormy</MenuItem>
                    <MenuItem value="foggy">Foggy</MenuItem>
                </Select>
            </FormControl>

            <FormControl fullWidth size="small" sx={{ mb: 1 }}>
                <InputLabel>Time of Day</InputLabel>
                <Select
                    value={selectedElement.properties.timeOfDay || 'day'}
                    label="Time of Day"
                    onChange={(e) => updateProperty('timeOfDay', e.target.value)}
                >
                    <MenuItem value="day">Day</MenuItem>
                    <MenuItem value="sunset">Sunset</MenuItem>
                    <MenuItem value="night">Night</MenuItem>
                </Select>
            </FormControl>

            <ColorInput
                label="Background Color"
                value={selectedElement.properties.backgroundColor || 'transparent'}
                onChange={(v) => updateProperty('backgroundColor', v)}
            />

            {/* Cloud Settings */}
            <Typography variant="caption" color="text.secondary" display="block" mb={0.5} mt={1.5}>
                CLOUDS
            </Typography>

            <TextInput
                label="Cloud Density"
                type="number"
                step={0.1}
                value={selectedElement.properties.cloudDensity ?? 0.5}
                onChange={(v) => updateProperty('cloudDensity', parseFloat(v as string) || 0)}
                helperText="0-1 (0 = no clouds, 1 = very cloudy)"
            />

            {/* Animation Settings */}
            <Typography variant="caption" color="text.secondary" display="block" mb={0.5} mt={1.5}>
                ANIMATION
            </Typography>

            <TextInput
                label="Animation Speed"
                type="number"
                step={0.1}
                value={selectedElement.properties.animationSpeed ?? 1}
                onChange={(v) => updateProperty('animationSpeed', parseFloat(v as string) || 0)}
                helperText="0.1-5 (1 = normal speed)"
            />

            <TextInput
                label="Particle Count"
                type="number"
                step={50}
                value={selectedElement.properties.particleCount ?? 500}
                onChange={(v) => updateProperty('particleCount', parseInt(v as string) || 0)}
                helperText="100-2000 (rain/snow particles)"
            />

            {/* Camera Settings */}
            <Typography variant="caption" color="text.secondary" display="block" mb={0.5} mt={1.5}>
                CAMERA
            </Typography>

            <TextInput
                label="Camera Angle"
                type="number"
                step={1}
                value={selectedElement.properties.cameraAngle ?? 30}
                onChange={(v) => updateProperty('cameraAngle', parseFloat(v as string) || 0)}
                helperText="0-90 degrees"
            />

            {/* Stars (Night Only) */}
            <Typography variant="caption" color="text.secondary" display="block" mb={0.5} mt={1.5}>
                STARS
            </Typography>

            <FormControlLabel
                control={
                    <Checkbox
                        checked={selectedElement.properties.showStars !== false}
                        onChange={(e) => updateProperty('showStars', e.target.checked)}
                    />
                }
                label="Show Stars (Night Only)"
            />
        </Box>
    );
};

export default WeatherProperties;
