/* eslint-disable react/jsx-pascal-case */

import React, { lazy, Suspense, useRef, useEffect } from 'react';
import ReactDOM from 'react-dom';
import type { PlacedElement, GridSettings } from './types/FrameEngine2_LayoutTypes';

// Lazy load Moveable (120KB) - only needed when element is selected
const Moveable = lazy(() => import('react-moveable'));

// Inject CSS to ensure Moveable controls are clickable AND inverse scale handles
if (typeof document !== 'undefined' && !document.getElementById('moveable-pointer-events-fix')) {
    const style = document.createElement('style');
    style.id = 'moveable-pointer-events-fix';
    style.innerHTML = `
        .moveable-control-box,
        .moveable-control,
        .moveable-line,
        .moveable-direction {
            pointer-events: auto !important;
        }

        /* Inverse scale the control box to keep handles constant size */
        .moveable-control-box {
            transform-origin: 0 0;
        }
    `;
    document.head.appendChild(style);
}

interface ViewportTransform {
    translateX: number;
    translateY: number;
    scale: number;
}

interface FrameEngine2_ControlsOverlayProps {
    /** The currently selected element ID */
    selectedElementId: string | null;

    /** The currently selected element data */
    selectedElement: PlacedElement | null;

    /** Viewport transform for coordinate conversion */
    viewport: ViewportTransform;

    /** Container ref for positioning context */
    containerRef: React.RefObject<HTMLDivElement | null>;

    /** Callback when element is updated */
    onUpdateElement?: (elementId: string, updates: Partial<PlacedElement>) => void;

    /** Grid settings for snapping */
    grid?: GridSettings;

    /** Layout mode for determining snapping behavior */
    layoutMode?: 'composite' | 'pixel';

    /** Callback when element is clicked */
    onClick?: (elementId: string) => void;
}

/**
 * Unscaled Controls Overlay - Renders Moveable controls outside the zoomed canvas
 *
 * This component exists in screen space (unscaled) while the canvas elements exist
 * in world space (scaled). It handles coordinate conversion between the two spaces.
 */
const FrameEngine2_ControlsOverlay: React.FC<FrameEngine2_ControlsOverlayProps> = ({
    selectedElementId,
    selectedElement,
    viewport,
    containerRef,
    onUpdateElement,
    grid,
    layoutMode = 'composite',
    onClick
}) => {
    const moveableRef = useRef<any>(null);

    // Update Moveable position when viewport changes (zoom/pan)
    useEffect(() => {
        if (moveableRef.current) {
            moveableRef.current.updateRect();
        }
    }, [viewport.scale, viewport.translateX, viewport.translateY]);

    // Don't render if no element is selected or element is locked
    if (!selectedElementId || !selectedElement || selectedElement.locked) {
        return null;
    }

    // Find the target element in the DOM
    const targetElement = document.querySelector(`[data-element-id="${selectedElementId}"]`) as HTMLDivElement | null;

    // Don't render if target element not found
    if (!targetElement) {
        console.warn('[ControlsOverlay] Target element not found:', selectedElementId);
        return null;
    }

    // Use portal to render in viewport space (not inside scaled container)
    return ReactDOM.createPortal(
        <div
            style={{
                position: 'fixed',
                inset: 0,
                pointerEvents: 'none',
                zIndex: 10000,
                overflow: 'visible'
            }}
        >

            <Suspense fallback={null}>
                <Moveable
                    ref={moveableRef}
                    target={targetElement}
                    draggable={true}
                    resizable={true}
                    rotatable={true}
                    origin={false}

                    // Make handles easier to click
                    controlPadding={5}

                    // Prevent element from blocking handle clicks
                    dragArea={false}

                    // Snap to grid - always enabled in pixel mode, respects setting in composite mode
                    snappable={layoutMode === 'pixel' ? true : grid?.snapToGrid}
                    snapGridWidth={grid?.gridSize}
                    snapGridHeight={grid?.gridSize}
                    isDisplayGridGuidelines={false}

                    // Strong snapping for Pixel_Mode - snap threshold is 0 (always snap)
                    // Composite mode uses 5px threshold for easier snapping feel
                    snapThreshold={layoutMode === 'pixel' ? 0 : 5}

                    // Snap both position and size to grid (edges, not center)
                    snapDirections={{
                        left: true, right: true, top: true, bottom: true,
                        center: false, middle: false
                    }}

                    // Resize handles: corners and edges
                    renderDirections={["nw", "n", "ne", "w", "e", "sw", "s", "se"]}

                    // Drag handlers
                    onDrag={({ transform }) => {
                        targetElement.style.transform = transform;
                    }}
                    onDragEnd={({ lastEvent }) => {
                        if (lastEvent && onUpdateElement) {
                            const beforeTranslate = lastEvent.beforeTranslate;
                            let x = beforeTranslate[0];
                            let y = beforeTranslate[1];

                            // Snap to grid if enabled (always in pixel mode, when enabled in composite mode)
                            const shouldSnap = layoutMode === 'pixel' || grid?.snapToGrid;
                            if (shouldSnap && grid?.gridSize) {
                                x = Math.round(x / grid.gridSize) * grid.gridSize;
                                y = Math.round(y / grid.gridSize) * grid.gridSize;
                            }

                            // Update element data
                            onUpdateElement(selectedElement.id, { x, y });

                            // Immediately apply snapped transform to element
                            const rotation = selectedElement.rotation || 0;
                            targetElement.style.transform = `translate(${x}px, ${y}px) rotate(${rotation}deg)`;

                            // Force Moveable to update to snapped position
                            if (moveableRef.current) {
                                setTimeout(() => moveableRef.current?.updateRect(), 0);
                            }
                        }
                    }}

                    // Resize handlers
                    onResize={({ width, height, drag }) => {
                        targetElement.style.width = `${width}px`;
                        targetElement.style.height = `${height}px`;
                        targetElement.style.transform = drag.transform;
                    }}
                    onResizeEnd={({ lastEvent }) => {
                        if (lastEvent && onUpdateElement) {
                            const beforeTranslate = lastEvent.drag.beforeTranslate;
                            let width = lastEvent.width;
                            let height = lastEvent.height;
                            let x = beforeTranslate[0];
                            let y = beforeTranslate[1];

                            // Snap to grid if enabled (always in pixel mode, when enabled in composite mode)
                            const shouldSnap = layoutMode === 'pixel' || grid?.snapToGrid;
                            if (shouldSnap && grid?.gridSize) {
                                width = Math.round(width / grid.gridSize) * grid.gridSize;
                                height = Math.round(height / grid.gridSize) * grid.gridSize;
                                x = Math.round(x / grid.gridSize) * grid.gridSize;
                                y = Math.round(y / grid.gridSize) * grid.gridSize;
                            }

                            // Update element data
                            onUpdateElement(selectedElement.id, { width, height, x, y });

                            // Immediately apply snapped size and transform to element
                            const rotation = selectedElement.rotation || 0;
                            targetElement.style.width = `${width}px`;
                            targetElement.style.height = `${height}px`;
                            targetElement.style.transform = `translate(${x}px, ${y}px) rotate(${rotation}deg)`;

                            // Force Moveable to update to snapped position
                            if (moveableRef.current) {
                                setTimeout(() => moveableRef.current?.updateRect(), 0);
                            }
                        }
                    }}

                    // Rotation handlers
                    onRotate={({ transform }) => {
                        targetElement.style.transform = transform;
                    }}
                    onRotateEnd={({ lastEvent }) => {
                        if (lastEvent && onUpdateElement) {
                            onUpdateElement(selectedElement.id, {
                                rotation: lastEvent.rotate
                            });
                        }
                    }}

                    // Click handler
                    onClick={() => {
                        onClick?.(selectedElement.id);
                    }}
                />
            </Suspense>
        </div>,
        document.body
    );
};

export default React.memo(FrameEngine2_ControlsOverlay);
